<section class="page-banner"><div class="container"><div class="section-label">ACCOUNT ADMINISTRATION</div><h1>Manage users</h1><p>Change account access and assign trusted club leaders for this local demonstration.</p></div></section><section class="section container"><?php require dirname(__DIR__).'/partials/admin_nav.php'; ?><div class="right-align"><a class="btn btn-primary" href="<?= e(url('admin/create')) ?>">+ Add administrator</a></div><form method="get" class="mini-search"><input name="r" type="hidden" value="admin/users"><input name="q" type="search" value="<?= e($search) ?>" placeholder="Search users by name, email, student number"><button class="btn btn-primary" type="submit">Find users</button></form><div class="card panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>User</th><th>Student number</th><th>Current role</th><th>Status</th><th>Change role</th><th>Access</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['full_name']) ?></strong><br><small><?= e($u['email']) ?></small></td><td><?= e($u['student_number']) ?></td><td><?= e(ucwords(str_replace('_',' ',$u['role']))) ?></td><td><?= status_pill($u['status']) ?></td><td><form method="post" action="<?= e(url('admin/user/role')) ?>" class="row-actions"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><select name="role" aria-label="Role for <?= e($u['full_name']) ?>" <?= (int)$u['id']===(int)user()['id']?'disabled':'' ?>><?php foreach(['student'=>'Student','club_leader'=>'Club leader','admin'=>'Administrator'] as $role=>$label): ?><option value="<?= $role ?>" <?= $u['role']===$role?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><button class="btn btn-outline btn-sm" type="submit" <?= (int)$u['id']===(int)user()['id']?'disabled':'' ?>>Save</button></form></td><td><?php if((int)$u['id']!==(int)user()['id']): ?><form method="post" action="<?= e(url('admin/user/status')) ?>" data-confirm="Change this user's account access?"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><button type="submit" name="status" value="<?= $u['status']==='active'?'suspended':'active' ?>" class="btn btn-outline btn-sm"><?= $u['status']==='active'?'Suspend':'Activate' ?></button></form><?php else: ?><span class="small-muted">Your account</span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$users): ?><tr><td colspan="6">No users found.</td></tr><?php endif; ?></tbody></table></div></div></section>
